"""Streaming LLM Client supporting strict JSON/Markdown synthesis and Mock Simulation Mode."""

from __future__ import annotations

import asyncio
import logging
import os
import random
from collections.abc import AsyncGenerator

from openai import AsyncOpenAI
from pydantic import BaseModel, Field

from src.core.config import Settings, get_settings
from src.retrieval.hybrid_retriever import ScoredChunk

logger = logging.getLogger("isorag.generator.llm")


class SynthesizedResponse(BaseModel):
    """Structured response payload generated by the LLM."""

    answer: str = Field(description="Synthesized markdown answer with inline [doc_id] citations")
    citations: list[str] = Field(
        default_factory=list, description="Referenced document identifiers"
    )
    model: str = Field(description="Model used for synthesis")
    raw_prompt_tokens: int | None = None
    completion_tokens: int | None = None


SYSTEM_PROMPT = """You are an accurate, hallucination-resistant multi-tenant enterprise AI assistant.
Answer the user's question STRICTLY based on the provided retrieved context.

Rules:
1. Always cite source documents inline using bracketed format, e.g., [doc-123].
2. If the context does not contain enough information, state clearly: "I do not have sufficient information in the provided context to answer this question."
3. Format output in clean GitHub-flavored markdown.
4. Never reveal confidential or cross-tenant information.
"""


class LLMClient:
    """Async client communicating with OpenAI or OpenAI-compatible inference endpoints.

    Supports Mock Simulation Mode via SIMULATION_MODE=true or unconfigured API keys.
    """

    def __init__(self, settings: Settings | None = None) -> None:
        self.settings = settings or get_settings()
        self.model = self.settings.llm_model
        self.temperature = self.settings.llm_temperature
        self.max_tokens = self.settings.llm_max_tokens
        self._client: AsyncOpenAI | None = None

    @property
    def is_simulation_mode(self) -> bool:
        """Determine whether Mock LLM Simulation Mode is active.

        Checks:
        1. Environment variable SIMULATION_MODE=true / 1 / yes
        2. Settings flag simulation_mode is True
        3. OPENAI_API_KEY is unset or set to mock placeholder
        """
        env_mode = os.getenv("SIMULATION_MODE", "").strip().lower()
        if env_mode in ("true", "1", "yes"):
            return True
        if self.settings.simulation_mode:
            return True
        if not self.settings.openai_api_key or self.settings.openai_api_key == "mock-key":
            return True
        return False

    def _get_client(self) -> AsyncOpenAI:
        if self._client is None:
            self._client = AsyncOpenAI(
                api_key=self.settings.openai_api_key or "mock-key",
                base_url=self.settings.openai_base_url,
            )
        return self._client

    def _build_messages(self, query: str, context: str) -> list[dict[str, str]]:
        user_content = f"Context:\n{context}\n\nQuestion: {query}"
        return [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": user_content},
        ]

    def _generate_mock_answer(
        self,
        query: str,
        context: str,
        scored_chunks: list[ScoredChunk],
    ) -> str:
        """Construct a deterministic markdown answer directly from pruned context chunks."""
        if not scored_chunks and not context.strip():
            return "I do not have sufficient information in the provided context to answer this question."

        lines: list[str] = [
            f"Based on the verified retrieved context, here is the answer for: **{query}**.\n"
        ]

        if scored_chunks:
            lines.append("### Key Findings\n")
            for item in scored_chunks:
                # Extract first sentence or snippet from chunk
                raw_text = item.chunk.content.strip()
                first_sentence = raw_text.split(". ")[0].rstrip(".")
                lines.append(f"- **[{item.chunk.doc_id}]**: {first_sentence}.")
            lines.append("")

        if context.strip():
            first_block = context.strip().split("\n\n")[0]
            lines.append(f"> {first_block[:280]}...\n")

        lines.append(
            "Synthesized deterministically in Mock LLM Mode with verified multi-tenant isolation."
        )
        return "\n".join(lines)

    async def generate(
        self,
        query: str,
        context: str,
        scored_chunks: list[ScoredChunk],
    ) -> SynthesizedResponse:
        """Generate complete synthesized response with citation tracking.

        In Mock Simulation Mode:
        - Simulates streaming inference latency via artificial sleep (50ms - 120ms).
        - Generates a deterministic markdown answer with citations directly from context chunks.
        - Requires no external API keys or network access.
        """
        citations = [c.chunk.doc_id for c in scored_chunks]

        # ----------------------------------------------------------------------
        # Mock Simulation Mode Branch
        # ----------------------------------------------------------------------
        if self.is_simulation_mode:
            logger.info("Executing LLM generation in Mock Simulation Mode (SIMULATION_MODE=true).")

            # Introduce artificial latency between 50ms and 120ms to mimic model inference
            sleep_duration = random.uniform(0.050, 0.120)
            await asyncio.sleep(sleep_duration)

            deterministic_answer = self._generate_mock_answer(query, context, scored_chunks)
            prompt_tokens = len(context.split())
            comp_tokens = len(deterministic_answer.split())

            return SynthesizedResponse(
                answer=deterministic_answer,
                citations=citations,
                model=f"{self.model}-simulated",
                raw_prompt_tokens=prompt_tokens,
                completion_tokens=comp_tokens,
            )

        # ----------------------------------------------------------------------
        # Live LLM Gateway Branch
        # ----------------------------------------------------------------------
        client = self._get_client()
        messages = self._build_messages(query, context)

        try:
            response = await client.chat.completions.create(
                model=self.model,
                messages=messages,  # type: ignore
                temperature=self.temperature,
                max_tokens=self.max_tokens,
            )
            content = response.choices[0].message.content or ""
            usage = response.usage

            return SynthesizedResponse(
                answer=content,
                citations=citations,
                model=self.model,
                raw_prompt_tokens=usage.prompt_tokens if usage else None,
                completion_tokens=usage.completion_tokens if usage else None,
            )
        except Exception as e:
            logger.error("LLM generation API error: %s", e)
            raise

    async def stream_generate(
        self,
        query: str,
        context: str,
        scored_chunks: list[ScoredChunk] | None = None,
    ) -> AsyncGenerator[str, None]:
        """Stream generated response tokens.

        In Mock Simulation Mode, introduces realistic inter-token streaming pauses.
        """
        if self.is_simulation_mode:
            answer = self._generate_mock_answer(query, context, scored_chunks or [])
            words = answer.split(" ")
            # Stream words with micro-delays (e.g., 5ms - 15ms per token)
            for word in words:
                await asyncio.sleep(random.uniform(0.005, 0.015))
                yield word + " "
            return

        client = self._get_client()
        messages = self._build_messages(query, context)

        stream = await client.chat.completions.create(
            model=self.model,
            messages=messages,  # type: ignore
            temperature=self.temperature,
            max_tokens=self.max_tokens,
            stream=True,
        )

        async for chunk in stream:
            delta = chunk.choices[0].delta.content
            if delta:
                yield delta
